library(creditratingsystem)
sat_near<-function(a,b,tol=1e-8)stopifnot(length(a)==length(b),all(abs(a-b)<=tol))
sat_error<-function(expr,code){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),e$code==code)}
sat_x<-sin((0:25)*.71)+(0:25)*.03;sat_dates<-sprintf('%04d-%02d-01',2000+(0:25)%/%12,(0:25)%%12+1L)
sat_history<-list(dates=as.list(sat_dates),values=lapply(sat_x,function(v)list(v)),variable_ids=list('x0'),frequency='monthly',release_dates=lapply(sat_dates,function(v)list(v)),units=list('index'))
sat_rows<-lapply(1:25,function(i)list(observation_id=paste0('o',i),entity_id='portfolio',date=sat_dates[i+1L],information_date=sat_dates[i+1L],known_at=sat_dates[i+1L],value=1+2*sat_x[i]+.1*sin(i*1.13)))
sat_training<-list(start=sat_dates[2],end=sat_dates[21],known_at=sat_dates[21],split_id='satellite_split',data_origin='SYNTHETIC');sat_split<-list(split_id='satellite_split',mode='TEMPORAL',train_ids=as.list(paste0('o',1:20)),validation_ids=as.list(paste0('o',21:25)),training_cutoff=sat_training$known_at)
sat_spec<-list(list(feature_id='x0_lag1',variable_id='x0',lag=1,unit='index',expected_sign='positive'));sat_target<-list(event='macro_state',horizon=1,time_unit='months',probability_measure='PHYSICAL',conditioning='PIT')
sat_args<-list(feature_spec=sat_spec,estimator='OLS',link='identity',split_plan=sat_split,training=sat_training,target=sat_target,target_unit='currency_units',model_id='satellite',model_version='1',residual_process='none')
sat_fit<-do.call(fit_satellite_model,c(list(target_series=sat_rows,macro_history=sat_history),sat_args));sat_design<-cbind(1,sat_x[1:20]);sat_y<-vapply(sat_rows[1:20],`[[`,numeric(1),'value');sat_oracle<-solve(crossprod(sat_design),crossprod(sat_design,sat_y));sat_near(unlist(sat_fit$model$parameters$coefficients),sat_oracle)
sat_changed<-sat_rows;for(i in 21:25)sat_changed[[i]]$value<-'unobserved holdout';sat_refit<-do.call(fit_satellite_model,c(list(target_series=sat_changed,macro_history=sat_history),sat_args));stopifnot(identical(sat_fit$model,sat_refit$model))
sat_cube<-list(schema_version='1.0',kind='ScenarioCube',axes=list('scenario','time','factor'),scenario_ids=list('s0','s1'),time_grid=list(1/12,2/12),time_unit='years',factor_ids=list('x0'),values=rep(list(list(list(0),list(0))),2),weights=list(.5,.5),units=list('index'),frequency='monthly',origin=sat_training$end,information_cutoff=sat_training$known_at,probability_measure='PHYSICAL',model_hash=paste(rep('a',64),collapse=''),scenario_origin='SIMULATED',data_origin='SYNTHETIC',sampling_contract=list(law='FORECAST_CONDITIONAL',conditioning_scope='PIT',initialization='LAST_OBSERVED_STATE'))
sat_draws<-list(kind='STANDARD_NORMAL',scenario_ids=sat_cube$scenario_ids,time_grid=sat_cube$time_grid,values=list(list(0,0),list(0,0)));sat_state<-list(as_of=sat_cube$origin,known_at=sat_cube$information_cutoff,mode='baseline_delta',macro_history=list(list(0)),baseline_link_path=list(10,11),reference_feature_path=list(list(0),list(0)),residual_state=0)
sat_result<-apply_satellite_model(sat_fit$model,sat_cube,sat_draws,sat_state);sat_near(unlist(sat_result$value$values),c(10,11,10,11));sat_state$mode<-'absolute';sat_state$macro_history<-list(list(3));sat_absolute<-apply_satellite_model(sat_fit$model,sat_cube,sat_draws,sat_state);sat_near(unlist(sat_absolute$value$values),rep(c(sat_oracle[1]+3*sat_oracle[2],sat_oracle[1]),2))
sat_bad<-sat_history;sat_bad$release_dates[[1]][[1]]<-'2010-01-01';sat_error(do.call(fit_satellite_model,c(list(target_series=sat_rows,macro_history=sat_bad),sat_args)),'LEAKAGE');sat_bad_args<-sat_args;sat_bad_args$split_plan$mode<-'ENTITY_TIME';sat_error(do.call(fit_satellite_model,c(list(target_series=sat_rows,macro_history=sat_history),sat_bad_args)),'LEAKAGE')
sat_covariances<-list()
for(covariance in c('classical','HC1','HAC')){
 w<-seq(.5,2,length.out=20);args<-sat_args;args$estimator<-'WLS';args$weights<-stats::setNames(as.list(w),paste0('o',1:20));args$covariance<-covariance;args$hac_lags<-2
 fit<-do.call(fit_satellite_model,c(list(target_series=sat_rows,macro_history=sat_history),args));bread<-solve(crossprod(sat_design*sqrt(w)));b<-bread%*%crossprod(sat_design,w*sat_y);e<-as.vector(sat_y-sat_design%*%b);scores<-sat_design*(w*e)
 if(covariance=='classical')expected<-bread*sum(w*e^2)/18 else{meat<-crossprod(scores);if(covariance=='HC1')meat<-meat*20/18 else for(lag in 1:2){cross<-crossprod(scores[(lag+1L):20,,drop=FALSE],scores[seq_len(20-lag),,drop=FALSE]);meat<-meat+(1-lag/3)*(cross+t(cross))};expected<-bread%*%meat%*%bread}
 sat_near(unlist(fit$model$parameters$coefficients),b);sat_near(unlist(fit$model$parameters$covariance),as.vector(t(expected)),1e-12);sat_covariances[[covariance]]<-fit$model$parameters
}
sat_binary<-sat_rows;for(i in seq_along(sat_binary))sat_binary[[i]]$value<-as.integer((i-1L)%%4 %in% c(0,2));sat_binargs<-sat_args;sat_binargs$estimator<-'GLM';sat_binargs$link<-'logit';sat_binargs$target_unit<-'probability';sat_binfit<-do.call(fit_satellite_model,c(list(target_series=sat_binary,macro_history=sat_history),sat_binargs));stopifnot(sat_binfit$model$parameters$residual_sigma==0,all(is.finite(unlist(sat_binfit$model$parameters$coefficients))))
sat_future_transform<-sat_history;sat_future_transform$fit_window<-list(start=sat_dates[1],end=tail(sat_dates,1),known_at=tail(sat_dates,1));sat_error(do.call(fit_satellite_model,c(list(target_series=sat_rows,macro_history=sat_future_transform),sat_args)),'LEAKAGE')
